//! `completions <shell>`: the bash, zsh, fish or PowerShell completion
//! script, generated by clap_complete from the clap definition (so it never
//! drifts), plus a few lines of shell that ask the hidden
//! `illumio-tui __complete <kind>` helper for values only known locally.
//!
//! The helper reads local files only and never builds a client: the config
//! file (`profiles`, the profile's saved filter names, and which profile
//! and whether `completion_cache` is on) and the profile's names cache, `names.json` (labels, label keys,
//! apps, hostnames, services, IP lists, label groups; see
//! [`crate::names`]). That file is filled as a side effect of the lists
//! the CLI and the TUI read anyway, and by `completions refresh`; with no
//! file there is nothing to offer, and a Tab never becomes a request.
//!
//! The dynamic part is grafted onto clap_complete's stable static output
//! (`clap_complete`'s dynamic engine is behind `unstable-dynamic`).
//!
//! Profile names: zsh gets an action function for `--profile` and `profile
//! use`, bash a wrapper that answers them before the generated function,
//! fish an `-a "(illumio-tui __complete profiles)"` on those arguments.
//!
//! PCE names, for the arguments [`HOOKS`] lists: each one's help carries a
//! marker in the command the scripts are generated from. zsh swaps that
//! line's action for `_illumio-tui__names KIND`; fish appends an `-a` to it
//! (and writes its own line for a positional or a third-level subcommand,
//! which clap_complete leaves out); the marker is then dropped. bash and
//! PowerShell show no argument help, so they get a table instead, keyed on
//! the subcommand the generated code has worked out (`cmd` in bash,
//! `$command` in PowerShell) and the previous word: bash consults it from
//! inside the generated function, PowerShell before the generated `switch`
//! (where `--profile` and `profile use` get their names too). The current
//! `--profile` and `--config`, when on the line, go to the helper. The
//! edits are anchored on generated text the tests pin.
use super::Cli;
use crate::config;
use crate::names::{self, Kind};
use clap::{CommandFactory, ValueEnum};
use std::ffi::OsString;
use std::io::Write;
use std::path::PathBuf;

const BIN: &str = "illumio-tui";
/// The hidden helper's argv[1]; handled in `main` before clap parses.
pub const HELPER: &str = "__complete";

#[derive(clap::Args, Debug, Clone)]
#[command(args_conflicts_with_subcommands = true, subcommand_negates_reqs = true)]
pub struct CompletionsArgs {
    #[command(subcommand)]
    pub action: Option<CompletionsAction>,
    /// The shell to print the script for
    #[arg(value_enum, required = true)]
    pub shell: Option<Shell>,
}

#[derive(clap::Subcommand, Debug, Clone)]
pub enum CompletionsAction {
    /// Fill the profile's PCE names cache, which completion offers labels, apps, hostnames,
    /// services, IP lists and label groups from
    ///
    /// Requests: one paged GET each of labels, label groups, IP lists, services and workloads,
    /// throttled and counted like any command. Prints the counts and the cache's age. The
    /// lists the CLI and the TUI read anyway keep it current too; nothing refreshes it on its
    /// own. Needs a config file profile with its own host and org_id (none from flags or
    /// PCE_HOST/PCE_PORT/PCE_ORG_ID); `completion_cache = false` keeps names off disk.
    Refresh(RefreshArgs),
}

#[derive(clap::Args, Debug, Clone)]
pub struct RefreshArgs {
    /// Delete the profile's names cache instead (no request; the profile from --profile,
    /// ILLUMIO_PROFILE of the shell, not of an --env-file, or default_profile)
    #[arg(long)]
    pub clear: bool,
}

#[derive(ValueEnum, Debug, Clone, Copy, PartialEq, Eq)]
pub enum Shell {
    Bash,
    Zsh,
    Fish,
    #[value(name = "powershell")]
    PowerShell,
}

/// Prints the script for `args.shell` to stdout.
pub fn run(args: &CompletionsArgs) -> Result<(), super::CliError> {
    let shell = args
        .shell
        .ok_or_else(|| super::CliError::Args("completions: name a shell".into()))?;
    let mut out = std::io::stdout().lock();
    out.write_all(script(shell).as_bytes())?;
    Ok(())
}

