/// The marker a hooked argument's help carries into the generated text.
const MARK: &str = "__NAMES_";

fn marker(kind: Kind) -> String {
    format!(" {MARK}{}__", kind.name())
}

/// `line` without its marker, and the marker's kind; `None` when it has none.
fn take_marker(line: &str) -> Option<(Kind, String)> {
    let at = line.find(&format!(" {MARK}"))?;
    let rest = &line[at + 1 + MARK.len()..];
    let end = rest.find("__")?;
    let kind = Kind::parse(&rest[..end])?;
    Some((kind, format!("{}{}", &line[..at], &rest[end + 2..])))
}

/// `text` with every marker dropped (where a shell has no use for them).
fn strip_markers(text: &str) -> String {
    text.split_inclusive('\n')
        .map(|l| take_marker(l).map_or_else(|| l.to_string(), |(_, l)| l))
        .collect()
}

/// The clap command as completion sees it: free-text arguments whose
/// accepted values are known get them as hints here, not in the parser
/// (the PCE or the TUI decides what they accept; adding a value parser
/// would change what the CLI accepts); [`HOOKS`]' arguments get a marker.
fn completion_command() -> clap::Command {
    let mut cmd = Cli::command()
        .mut_arg("theme", |a| a.value_parser(["dark", "light"]))
        .mut_subcommand("events", |c| {
            c.mut_arg("severity", |a| {
                a.value_parser([
                    "emerg", "alert", "crit", "err", "warning", "notice", "info", "debug",
                ])
            })
            .mut_arg("status", |a| a.value_parser(["success", "failure"]))
        });
    for &(path, arg, kind) in HOOKS {
        mark_arg(&mut cmd, path, arg, kind);
    }
    cmd
}

/// The argument `arg` of the subcommand at `path`, if there is one.
fn find_arg<'a>(cmd: &'a clap::Command, path: &[&str], arg: &str) -> Option<&'a clap::Arg> {
    let sub = path
        .iter()
        .try_fold(cmd, |c, name| c.find_subcommand(name))?;
    sub.get_arguments().find(|a| match arg.strip_prefix("--") {
        Some(long) => a.get_long() == Some(long),
        None => a.is_positional() && a.get_id().as_str() == arg,
    })
}

/// Appends `kind`'s marker to the help of `arg` at `path`.
fn mark_arg(cmd: &mut clap::Command, path: &[&str], arg: &str, kind: Kind) {
    let Some(id) = find_arg(cmd, path, arg).map(|a| a.get_id().clone()) else {
        return;
    };
    let Some(sub) = path
        .iter()
        .try_fold(cmd, |c, name| c.find_subcommand_mut(name))
    else {
        return;
    };
    *sub = std::mem::take(sub).mut_arg(id, |a| {
        let help = a.get_help().map(ToString::to_string).unwrap_or_default();
        a.help(format!("{help}{}", marker(kind)))
    });
}

/// The completion script for `shell`.
pub fn script(shell: Shell) -> String {
    let mut cmd = completion_command();
    let mut buf = Vec::new();
    let generator = match shell {
        Shell::Bash => clap_complete::Shell::Bash,
        Shell::Zsh => clap_complete::Shell::Zsh,
        Shell::Fish => clap_complete::Shell::Fish,
        Shell::PowerShell => clap_complete::Shell::PowerShell,
    };
    clap_complete::generate(generator, &mut cmd, BIN, &mut buf);
    let text = String::from_utf8(buf).expect("clap_complete writes UTF-8");
    let text = match shell {
        Shell::Bash => bash_dynamic(&text),
        Shell::Zsh => zsh_dynamic(&text),
        Shell::Fish => fish_dynamic(&text),
        Shell::PowerShell => powershell_dynamic(&text),
    };
    strip_markers(&text)
}

/// `profile use`'s positional as clap_complete writes it (its id and help).
const PROFILE_USE_ZSH: &str = ":name -- Profile name from the config file:_default'";

/// zsh: `--profile`'s `PROFILE` and `profile use`'s name complete
/// through `_illumio-tui__profiles`, each hooked argument through
/// `_illumio-tui__names KIND`; both defined before the script's entry.
fn zsh_dynamic(text: &str) -> String {
    const FUNC: &str = r#"(( $+functions[_illumio-tui__profiles] )) ||
(( $+functions[_illumio-tui__line_args] )) ||
_illumio-tui__line_args() {
    # `reply`: the options named in "$@" with their values, from the whole
    # line (a subcommand's _arguments, and its opt_args, sees its own words
    # only), as `--opt VALUE` or `--opt=VALUE`.
    local -a w
    local i
    reply=()
    w=(${(Q)${(z)LBUFFER}})
    for (( i = 1; i < $#w; i++ )); do
        if (( $@[(Ie)$w[i]] )); then
            reply+=($w[i] ${~w[i+1]})
        elif [[ $w[i] == --*=* ]] && (( $@[(Ie)${w[i]%%=*}] )); then
            reply+=(${w[i]%%=*} ${~w[i]#*=})
        fi
    done
}

(( $+functions[_illumio-tui__profiles] )) ||
_illumio-tui__profiles() {
    local -a profiles reply
    _illumio-tui__line_args --config
    profiles=(${(f)"$(illumio-tui __complete profiles $reply 2>/dev/null)"})
    _wanted profiles expl 'profile' compadd -a profiles
}

(( $+functions[_illumio-tui__names] )) ||
_illumio-tui__names() {
    local -a values reply
    _illumio-tui__line_args --config --profile
    values=(${(f)"$(illumio-tui __complete $1 $reply -- "${(Q)PREFIX}" 2>/dev/null)"})
    _wanted values expl $1 compadd -a values
}

"#;
    const ENTRY: &str = "if [ \"$funcstack[1]\" = \"_illumio-tui\" ]; then";
    let text: String = text
        .replace(":PROFILE:_default'", ":PROFILE:_illumio-tui__profiles'")
        .replace(
            PROFILE_USE_ZSH,
            ":name -- Profile name from the config file:_illumio-tui__profiles'",
        )
        .split_inclusive('\n')
        .map(|line| match take_marker(line) {
            Some((kind, line)) => match line.rfind(":_default'") {
                Some(at) => format!(
                    "{}: _illumio-tui__names {}'{}",
                    &line[..at],
                    kind.name(),
                    &line[at + ":_default'".len()..]
                ),
                None => line,
            },
            None => line.to_string(),
        })
        .collect();
    match text.find(ENTRY) {
        Some(at) => format!("{}{FUNC}{}", &text[..at], &text[at..]),
        None => text,
    }
}

/// bash's name for the subcommand at `path`, as the generated script sets
/// `cmd` (after [`bash_dynamic`]'s repair).
fn bash_cmd(path: &[&str]) -> String {
    path.iter().fold("illumio__tui".to_string(), |acc, p| {
        format!("{acc}__subcmd__{}", p.replace('-', "__subcmd__"))
    })
}

/// bash: `_illumio-tui__names` answers the hooked arguments, from inside
/// the generated function once it has worked out `cmd`. The word is taken
/// from `COMP_LINE`, as bash splits `key=value` and `wl:HOST` at `=` and
/// `:`; the values given back are what follows the last of those, quoted
/// by `printf %q` (a comma left bare: it is only special in braces).
const BASH_NAMES: &str = r##"
_illumio-tui__names() {
    local line="${COMP_LINE:0:COMP_POINT}" word prev head="" kind="" brk c i args=() comma='\,' bs='\'
    i=${#line}
    while (( i > 0 )); do
        if [[ "${line:i-1:1}" == [[:space:]] ]]; then
            (( i < 2 )) && break
            [[ "${line:i-2:1}" != "\\" ]] && break
        fi
        (( i-- ))
    done
    word="${line:i}"
    prev="${line:0:i}"
    prev="${prev%"${prev##*[![:space:]]}"}"
    prev="${prev##*[[:space:]]}"
    if [[ "${word}" == --*=* ]]; then
        head="${word%%=*}="
        prev="${head%=}"
        word="${word#*=}"
    fi
    case "$1,${prev}" in
@CASES@    esac
    [[ -n "${kind}" ]] || return 1
    for (( i = 1; i < COMP_CWORD; i++ )); do
        case "${COMP_WORDS[i]}" in
            --config|--profile)
                c="${COMP_WORDS[i+1]}"
                [[ "${c}" == "=" ]] && c="${COMP_WORDS[i+2]}"
                args+=("${COMP_WORDS[i]}" "${c}")
                ;;
        esac
    done
    word="${word//"${bs}"/}"
    brk="${head}${word}"
    brk="${brk%"${brk##*[=:]}"}"
    COMPREPLY=()
    while IFS= read -r c; do
        c="${head}${c}"
        printf -v c '%q' "${c#"${brk}"}"
        COMPREPLY+=("${c//"${comma}"/,}")
    done < <(illumio-tui __complete "${kind}" "${args[@]}" -- "${word}" 2>/dev/null)
    return 0
}
"##;

/// The `case` arms of [`BASH_NAMES`]: a flag's value after the flag, a
/// positional after any word that is not a flag.
fn bash_cases() -> String {
    let flags = HOOKS.iter().filter(|h| h.1.starts_with("--"));
    let positionals = HOOKS.iter().filter(|h| !h.1.starts_with("--"));
    let mut out = String::new();
    for &(path, arg, kind) in flags {
        out.push_str(&format!(
            "        {},{arg}) kind={} ;;\n",
            bash_cmd(path),
            kind.name()
        ));
    }
    for &(path, _, kind) in positionals {
        out.push_str(&format!(
            "        {},[!-]*) [[ \"${{word}}\" != -* ]] && kind={} ;;\n",
            bash_cmd(path),
            kind.name()
        ));
    }
    out
}

/// Where the generated function dispatches on `cmd`, once worked out.
const BASH_DISPATCH: &str = "\n    case \"${cmd}\" in\n";

/// bash: the generated script's subcommand cases repaired; a wrapper answers `--profile [=] <TAB>` and `profile use <TAB>`
/// from the helper and hands everything else to the generated function,
/// which asks `_illumio-tui__names` first.
fn bash_dynamic(text: &str) -> String {
    const WRAPPER: &str = r#"
_illumio-tui__dynamic() {
    local cur="${COMP_WORDS[COMP_CWORD]}" prev="" prev2="" i cfg=()
    (( COMP_CWORD >= 1 )) && prev="${COMP_WORDS[COMP_CWORD-1]}"
    (( COMP_CWORD >= 2 )) && prev2="${COMP_WORDS[COMP_CWORD-2]}"
    if [[ "${prev}" == "=" ]]; then
        prev="${prev2}"
        prev2=""
    elif [[ "${cur}" == "=" ]]; then
        prev="${prev}="
        cur=""
    fi
    if [[ "${prev}" == "--profile" || ( "${prev2}" == "profile" && "${prev}" == "use" ) ]]; then
        for (( i = 1; i < COMP_CWORD; i++ )); do
            [[ "${COMP_WORDS[i]}" == "--config" ]] && cfg=(--config "${COMP_WORDS[i+1]}")
        done
        # One name per line, quoted: never word-split or expanded.
        COMPREPLY=()
        while IFS= read -r i; do
            printf -v i '%q' "${i}"
            COMPREPLY+=("${i}")
        done < <(illumio-tui __complete profiles "${cfg[@]}" -- "${cur}" 2>/dev/null)
        return 0
    fi
    _illumio__tui "$@"
}
"#;
    const REGISTER: &str = "complete -F _illumio__tui ";
    let at = text
        .find("\nif [[ \"${BASH_VERSINFO[0]}\" -eq 4")
        .unwrap_or(text.len());
    let (body, tail) = text.split_at(at);
    // clap_complete 4.6 names a hyphenated binary's subcommand cases
    // `illumio__subcmd__tui__…` but sets `cmd` to `illumio__tui__…`, so no
    // subcommand case ever matched; align the case labels.
    let body = body.replace("illumio__subcmd__tui", "illumio__tui");
    let body = body.replacen(
        BASH_DISPATCH,
        &format!("\n    _illumio-tui__names \"${{cmd}}\" && return 0{BASH_DISPATCH}"),
        1,
    );
    format!(
        "{body}{}{WRAPPER}{}",
        BASH_NAMES.replace("@CASES@", &bash_cases()),
        tail.replace(REGISTER, "complete -F _illumio-tui__dynamic ")
    )
}

/// fish's condition for the subcommand at `path`, as the generated script
/// writes it.
fn fish_condition(path: &[&str]) -> String {
    let mut c = format!("__fish_illumio_tui_using_subcommand {}", path[0]);
    for p in &path[1..] {
        c.push_str(&format!("; and __fish_seen_subcommand_from {p}"));
    }
    c
}

/// fish: `--profile` and `profile use` offer the helper's profile names;
/// each hooked argument the helper's names, through
/// `__fish_illumio_tui_names KIND`: on its generated line, else on a line
/// of its own.
fn fish_dynamic(text: &str) -> String {
    const VALUES: &str = r#"-f -a "(illumio-tui __complete profiles 2>/dev/null)""#;
    const FUNC: &str = r#"
function __fish_illumio_tui_names
    set -l args
    set -l words (commandline -opc)
    for i in (seq (count $words))
        switch $words[$i]
            case --config --profile
                set -l j (math $i + 1)
                set -q words[$j]; and set -a args $words[$i] $words[$j]
            case '--config=*' '--profile=*'
                set -a args (string split -m 1 = -- $words[$i])
        end
    end
    illumio-tui __complete $argv[1] $args -- (commandline -ct | string unescape) 2>/dev/null
end

"#;
    let mut out = String::with_capacity(text.len() + 4096);
    for line in text.lines() {
        let line = match take_marker(line) {
            Some((kind, line)) => {
                format!(
                    "{line} -f -a \"(__fish_illumio_tui_names {})\"",
                    kind.name()
                )
            }
            None => line.to_string(),
        };
        out.push_str(&line);
        if line.starts_with("complete -c illumio-tui ") && line.contains(" -l profile ") {
            out.push(' ');
            out.push_str(VALUES);
        }
        out.push('\n');
    }
    out.push_str(&format!(
        "complete -c illumio-tui -n \"__fish_illumio_tui_using_subcommand profile; and __fish_seen_subcommand_from use\" {VALUES}\n"
    ));
    out.push_str(FUNC);
    for &(path, arg, kind) in HOOKS {
        // clap_complete writes no line for a positional, nor any for a
        // third-level subcommand (`policy rules add`).
        let flag = match arg.strip_prefix("--") {
            Some(_) if path.len() <= FISH_DEPTH => continue,
            Some(long) => format!(" -l {long} -r"),
            None => String::new(),
        };
        out.push_str(&format!(
            "complete -c illumio-tui -n \"{}\"{flag} -f -a \"(__fish_illumio_tui_names {})\"\n",
            fish_condition(path),
            kind.name()
        ));
    }
    out
}

/// The deepest subcommand clap_complete's fish script writes options for.
const FISH_DEPTH: usize = 2;

/// PowerShell's name for the subcommand at `path`, as the generated script
/// joins `$command`.
fn powershell_command(path: &[&str]) -> String {
    format!("{BIN};{}", path.join(";"))
}

/// PowerShell: before the generated `switch`, a value of a hooked argument
/// (the word after the flag, `--flag=` and the word, or a positional
/// right after its subcommand), of `--profile` or of `profile use` is
/// answered from the helper; quoted when it holds a space, a comma or
/// another character PowerShell would read, every single quote doubled:
/// ASCII `'` and U+2018 to U+201B, which PowerShell also takes for one
/// (written as `\u` escapes, so the script stays ASCII).
const POWERSHELL_NAMES: &str = r#"    $namesKinds = @{
@KINDS@    }
    $namesHead = ''
    $namesWord = $wordToComplete
    $namesPrev = "$(($commandElements | Where-Object { $_.Extent.EndOffset -lt ($cursorPosition - $wordToComplete.Length) } | Select-Object -Last 1).Extent.Text)"
    if ($wordToComplete -match '^(--[^=]+)=(.*)$') {
        $namesHead = $Matches[1] + '='
        $namesPrev = $Matches[1]
        $namesWord = $Matches[2]
    }
    $namesKind = $namesKinds["$command $namesPrev"]
    if ($namesPrev -eq '--profile') {
        $namesKind = 'profiles'
    }
    if (-not $namesKind -and -not $namesPrev.StartsWith('-') -and -not $namesWord.StartsWith('-')) {
        $namesKind = $namesKinds[$command]
    }
    if ($namesKind) {
        $namesArgs = @('__complete', $namesKind)
        for ($n = 1; $n -lt $commandElements.Count - 1; $n++) {
            $t = $commandElements[$n].Extent.Text
            if ($t -eq '--config' -or $t -eq '--profile') {
                $namesArgs += @($t, $commandElements[$n + 1].Extent.Text)
            }
        }
        $namesArgs += @('--', $namesWord)
        & 'illumio-tui' @namesArgs 2>$null | ForEach-Object {
            $text = $namesHead + $_
            if ($text -match '[\s''"`$@(){};,&|<>#\u2018-\u201B]') {
                $text = "'" + ($text -replace '[''\u2018-\u201B]', '$0$0') + "'"
            }
            [CompletionResult]::new($text, $_, [CompletionResultType]::ParameterValue, $_)
        }
        return
    }

"#;

/// Where the generated script starts matching `$command`.
const POWERSHELL_SWITCH: &str = "    $completions = @(switch ($command) {";

/// PowerShell: [`POWERSHELL_NAMES`] before the generated `switch`, its
/// table keyed `"<command> <flag>"` (a flag's value) or `"<command>"` (a
/// positional).
fn powershell_dynamic(text: &str) -> String {
    let kinds: String = HOOKS
        .iter()
        .map(|&(path, arg, kind)| {
            let key = match arg.starts_with("--") {
                true => format!("{} {arg}", powershell_command(path)),
                false => powershell_command(path),
            };
            format!("        '{key}' = '{}'\n", kind.name())
        })
        .collect();
    let kinds = format!("        '{BIN};profile;use' = 'profiles'\n{kinds}");
    let names = POWERSHELL_NAMES.replace("@KINDS@", &kinds);
    text.replacen(POWERSHELL_SWITCH, &format!("{names}{POWERSHELL_SWITCH}"), 1)
}

/// `illumio-tui __complete <kind> [--config PATH] [--profile NAME] [--]
/// [prefix]`: one value per line, from local files only; nothing (and
/// success) when there is nothing to offer, the kind is unknown, or a file
/// cannot be read. `profiles`: the config file's profiles; any other kind
/// ([`Kind`]): the profile's names cache, when `completion_cache` is on.
pub fn helper(args: &[OsString], out: &mut impl Write) -> std::io::Result<()> {
    let mut kind = None;
    let mut config_path: Option<PathBuf> = None;
    let mut profile: Option<String> = None;
    let mut prefix = String::new();
    let mut it = args.iter();
    while let Some(a) = it.next() {
        if a == "--" {
            prefix = it
                .next()
                .map(|p| p.to_string_lossy().into_owned())
                .unwrap_or_default();
            break;
        } else if a == "--config" {
            config_path = it.next().map(PathBuf::from);
        } else if a == "--profile" {
            profile = it.next().and_then(|p| p.to_str()).map(String::from);
        } else if kind.is_none() {
            kind = a.to_str();
        } else {
            prefix = a.to_string_lossy().into_owned();
        }
    }
    let config_path = config_path.unwrap_or_else(config::default_config_path);
    let values = match kind {
        Some("profiles") => profiles(&config_path)
            .into_iter()
            .filter(|v| v.starts_with(&prefix))
            .collect(),
        Some(k) => match Kind::parse(k) {
            Some(kind) if kind.filters().is_some() => {
                saved_filters(&config_path, profile, kind, &prefix)
            }
            Some(kind) => match names::lookup(&config_path, profile) {
                Some(n) => names::complete(kind, &n, &prefix),
                None => Vec::new(),
            },
            None => Vec::new(),
        },
        None => Vec::new(),
    };
    for v in &values {
        writeln!(out, "{v}")?;
    }
    Ok(())
}

/// The saved filter names of `kind`'s screen starting with `prefix`, of
/// the profile (`--profile`, `ILLUMIO_PROFILE`, `default_profile`), from
/// the config file alone.
fn saved_filters(
    path: &std::path::Path,
    named: Option<String>,
    kind: Kind,
    prefix: &str,
) -> Vec<String> {
    let (Some(screen), Ok(file)) = (kind.filters(), config::load_config_file(path)) else {
        return Vec::new();
    };
    let named = named.or_else(|| {
        std::env::var("ILLUMIO_PROFILE")
            .ok()
            .map(|s| s.trim().to_string())
            .filter(|s| !s.is_empty())
    });
    let (profile, _) = config::profile_name(&file, named);
    file.profiles
        .get(&profile)
        .map(|p| p.filters.names(screen))
        .unwrap_or_default()
        .into_iter()
        .filter(|n| n.starts_with(prefix))
        .collect()
}

/// The config file's profile names, sorted; none when it is missing or
/// unreadable. Reads the file and nothing else (no secret command runs).
fn profiles(path: &std::path::Path) -> Vec<String> {
    config::load_config_file(path)
        .map(|f| f.profiles.into_keys().collect())
        .unwrap_or_default()
}

#[cfg(test)]
mod tests {
    use super::*;

    fn run_helper(args: &[&str]) -> String {
        let args: Vec<OsString> = args.iter().map(OsString::from).collect();
        let mut out = Vec::new();
        helper(&args, &mut out).unwrap();
        String::from_utf8(out).unwrap()
    }

    #[test]
    fn helper_lists_profiles_from_the_config_file() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("config.toml");
        std::fs::write(
            &path,
            "default_profile = \"lab\"\n[profiles.lab]\nhost = \"a\"\n[profiles.prod]\nhost = \"b\"\n",
        )
        .unwrap();
        let p = path.to_str().unwrap();
        assert_eq!(run_helper(&["profiles", "--config", p]), "lab\nprod\n");
        assert_eq!(run_helper(&["profiles", "--config", p, "pr"]), "prod\n");
    }

    #[test]
    fn helper_lists_a_screens_saved_filter_names_from_the_config_file() {
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("config.toml");
        std::fs::write(
            &path,
            "completion_cache = false
[profiles.lab]
host = \"a\"
\
             [profiles.lab.filters.traffic.prod-blocked]
src = \"env=prod\"
\
             [profiles.lab.filters.traffic.lab]
src = 1
\
             [profiles.lab.filters.policy]
deny-prod = \"deny\"
\
             [profiles.other.filters.traffic.elsewhere]
src = \"x=y\"
",
        )
        .unwrap();
        let p = path.to_str().unwrap();
        let ask = |kind: &str, prefix: &str| {
            run_helper(&[kind, "--config", p, "--profile", "lab", "--", prefix])
        };
        // No names cache needed (completion_cache = false), none written.
        assert_eq!(ask("filters-traffic", ""), "lab\nprod-blocked\n");
        assert_eq!(ask("filters-traffic", "pr"), "prod-blocked\n");
        assert_eq!(ask("filters-policy", ""), "deny-prod\n");
        assert_eq!(ask("filters-events", ""), "");
        assert_eq!(
            run_helper(&["filters-traffic", "--config", p, "--profile", "other"]),
            "elsewhere\n"
        );
        assert_eq!(std::fs::read_dir(dir.path()).unwrap().count(), 1);
    }

    #[test]
    fn helper_prints_nothing_without_a_file_or_for_unknown_kinds() {
        let dir = tempfile::tempdir().unwrap();
        let missing = dir.path().join("nope.toml");
        let m = missing.to_str().unwrap();
        assert_eq!(run_helper(&["profiles", "--config", m]), "");
        assert_eq!(run_helper(&["labels", "--config", m]), "");
        assert_eq!(run_helper(&[]), "");
        let broken = dir.path().join("broken.toml");
        std::fs::write(&broken, "[[[").unwrap();
        assert_eq!(
            run_helper(&["profiles", "--config", broken.to_str().unwrap()]),
            ""
        );
    }

    /// Every top-level subcommand, by name, from the definition.
    fn top_level() -> Vec<String> {
        Cli::command()
            .get_subcommands()
            .map(|c| c.get_name().to_string())
            .collect()
    }

    #[test]
    fn scripts_name_every_subcommand_and_hook_the_helper() {
        let names = top_level();
        assert!(names.contains(&"completions".to_string()));
        for shell in [Shell::Bash, Shell::Zsh, Shell::Fish] {
            let s = script(shell);
            for name in &names {
                assert!(s.contains(name.as_str()), "{shell:?} misses {name}");
            }
            for nested in ["rulesets", "provision", "deny-rules", "import"] {
                assert!(s.contains(nested), "{shell:?} misses {nested}");
            }
            // The hidden helper is not offered as a subcommand.
            assert!(!s.contains("\"__complete\""), "{shell:?}");
            assert!(s.contains("illumio-tui __complete profiles"), "{shell:?}");
        }
    }

    #[test]
    fn zsh_profile_values_all_use_the_helper() {
        let s = script(Shell::Zsh);
        assert!(!s.contains(":PROFILE:_default"));
        assert!(!s.contains(PROFILE_USE_ZSH));
        assert!(
            s.contains("':name -- Profile name from the config file:_illumio-tui__profiles'"),
            "profile use"
        );
        assert!(s.contains("--profile=[") && s.contains(":PROFILE:_illumio-tui__profiles'"));
        assert!(s.contains("_illumio-tui__profiles() {"));
        // Value hints and enum values reach the script.
        assert!(s.contains("--config=[") && s.contains("_files"));
        assert!(s.contains("_hosts"));
        assert!(s.contains("(dark light)"));
        assert!(s.contains("(emerg alert crit err warning notice info debug)"));
        assert!(s.contains("(success failure)"));
    }

    #[test]
    fn bash_registers_the_wrapper() {
        let s = script(Shell::Bash);
        assert!(s.contains("complete -F _illumio-tui__dynamic "));
        assert!(!s.contains("complete -F _illumio__tui "));
        assert!(
            s.contains("_illumio__tui() {"),
            "the generated function the wrapper calls"
        );
        assert!(s.contains("_illumio-tui__dynamic() {"));
        assert!(!s.contains("illumio__subcmd__tui"));
        assert!(s.contains("\n        illumio__tui__subcmd__policy)\n"));
    }

    #[test]
    fn powershell_script_registers_a_completer_for_every_subcommand() {
        let s = script(Shell::PowerShell);
        assert!(s.contains("Register-ArgumentCompleter -Native -CommandName 'illumio-tui'"));
        for name in top_level() {
            assert!(s.contains(&format!("'{name}'")), "misses {name}");
        }
        assert!(!s.contains("[CompletionResult]::new('__complete'"));
        assert_eq!(
            Shell::from_str("powershell", false),
            Ok(Shell::PowerShell),
            "the CLI spelling"
        );
    }

    #[test]
    fn fish_profile_lines_use_the_helper() {
        let s = script(Shell::Fish);
        let profile_lines: Vec<&str> = s.lines().filter(|l| l.contains(" -l profile ")).collect();
        assert!(!profile_lines.is_empty());
        assert!(profile_lines.iter().all(|l| l.ends_with("2>/dev/null)\"")));
        assert!(s.contains("function __fish_illumio_tui_using_subcommand"));
    }

    #[test]
    fn every_hook_names_an_argument_of_the_cli() {
        let cmd = Cli::command();
        for &(path, arg, _) in HOOKS {
            assert!(find_arg(&cmd, path, arg).is_some(), "{path:?} {arg}");
        }
        let marked = completion_command();
        for &(path, arg, kind) in HOOKS {
            let help = find_arg(&marked, path, arg).unwrap().get_help().unwrap();
            assert!(help.to_string().ends_with(&marker(kind)), "{path:?} {arg}");
        }
    }

    #[test]
    fn filters_default_completes_the_screens_saved_names() {
        let fish = script(Shell::Fish);
        for screen in ["traffic", "policy", "events", "workloads"] {
            let line = format!(
                "__fish_seen_subcommand_from default; and __fish_seen_subcommand_from {screen}\" \
                 -f -a \"(__fish_illumio_tui_names filters-{screen})\""
            );
            assert!(fish.contains(&line), "{screen}");
        }
        assert!(script(Shell::Zsh).contains(
            "'::name -- The saved filter to make the default (or --unset): _illumio-tui__names filters-policy'"
        ));
    }

    #[test]
    fn no_shell_keeps_a_marker() {
        for shell in [Shell::Bash, Shell::Zsh, Shell::Fish, Shell::PowerShell] {
            assert!(!script(shell).contains(MARK), "{shell:?}");
        }
        assert_eq!(
            take_marker(&format!("'--x=[Help{}]:X:_default'", marker(Kind::Apps))),
            Some((Kind::Apps, "'--x=[Help]:X:_default'".into()))
        );
        assert_eq!(take_marker("'--x=[Help]:X:_default'"), None);
    }

    /// Every hooked argument completes through the helper, once.
    #[test]
    fn zsh_and_fish_hook_every_argument() {
        let zsh = script(Shell::Zsh);
        assert_eq!(zsh.matches(": _illumio-tui__names ").count(), HOOKS.len());
        assert!(zsh.contains("_illumio-tui__names() {"));
        assert!(zsh.contains("illumio-tui __complete $1 $reply -- \"${(Q)PREFIX}\""));
        // Through `_arguments` as written, not with its options first.
        assert!(!zsh.contains(":_illumio-tui__names "));
        assert!(zsh.contains(
            "'*--label=[Label key=value (repeatable)]:LABELS: _illumio-tui__names labels'"
        ));
        assert!(zsh.contains(": _illumio-tui__names apps'"));
        let fish = script(Shell::Fish);
        assert_eq!(
            fish.matches("-f -a \"(__fish_illumio_tui_names ").count(),
            HOOKS.len()
        );
        assert!(fish.contains("function __fish_illumio_tui_names"));
        // The conditions of the lines added for positionals are the
        // generated ones.
        let generated = {
            let mut cmd = completion_command();
            let mut buf = Vec::new();
            clap_complete::generate(clap_complete::Shell::Fish, &mut cmd, BIN, &mut buf);
            String::from_utf8(buf).unwrap()
        };
        for &(path, _, _) in HOOKS.iter().filter(|h| h.0.len() <= FISH_DEPTH) {
            let cond = format!("-n \"{}", fish_condition(path));
            assert!(generated.contains(&cond), "{cond}");
        }
        assert!(fish.contains(
            "-n \"__fish_illumio_tui_using_subcommand policy; and __fish_seen_subcommand_from rules; and __fish_seen_subcommand_from add\" -l provider -r -f -a \"(__fish_illumio_tui_names actors)\""
        ));
    }

    #[test]
    fn bash_asks_the_names_hook_for_every_hooked_subcommand() {
        let s = script(Shell::Bash);
        assert!(s.contains(&format!(
            "\n    _illumio-tui__names \"${{cmd}}\" && return 0{BASH_DISPATCH}"
        )));
        assert_eq!(s.matches("_illumio-tui__names \"${cmd}\"").count(), 1);
        for &(path, arg, kind) in HOOKS {
            let name = bash_cmd(path);
            assert!(s.contains(&format!("cmd=\"{name}\"\n")), "{name}");
            let arm = match arg.starts_with("--") {
                true => format!("        {name},{arg}) kind={} ;;\n", kind.name()),
                false => format!(
                    "        {name},[!-]*) [[ \"${{word}}\" != -* ]] && kind={} ;;\n",
                    kind.name()
                ),
            };
            assert!(s.contains(&arm), "{arm}");
        }
    }

    #[test]
    fn powershell_answers_hooked_arguments_before_the_generated_switch() {
        let s = script(Shell::PowerShell);
        let names = s.find("    $namesKinds = @{").expect("the names block");
        assert!(names < s.find(POWERSHELL_SWITCH).expect("the generated switch"));
        for &(path, arg, kind) in HOOKS {
            let command = powershell_command(path);
            assert!(
                s.contains(&format!("        '{command}' {{\n")),
                "{command}"
            );
            let key = match arg.starts_with("--") {
                true => format!("{command} {arg}"),
                false => command,
            };
            assert!(
                s.contains(&format!("        '{key}' = '{}'\n", kind.name())),
                "{key}"
            );
        }
        assert!(s.contains("& 'illumio-tui' @namesArgs 2>$null"));
        assert!(s.contains("        'illumio-tui;profile;use' = 'profiles'\n"));
        assert!(s.contains("    if ($namesPrev -eq '--profile') {"));
    }

    /// A PCE value that holds a typographic single quote (PowerShell reads
    /// U+2018 to U+201B as `'` too) is quoted with each of them doubled,
    /// so `x’;calc;’` cannot end the literal. Run in pwsh when installed.
    #[test]
    fn powershell_doubles_every_kind_of_single_quote() {
        let s = script(Shell::PowerShell);
        let test = s.find("            if ($text -match").expect("the quoting");
        let end = test + s[test..].find("            }\n").unwrap() + 14;
        let quoting = &s[test..end];
        assert!(quoting.contains(r"#\u2018-\u201B]')"), "{quoting}");
        assert!(
            quoting.contains(r"-replace '[''\u2018-\u201B]', '$0$0'"),
            "{quoting}"
        );
        assert!(quoting.is_ascii(), "written with escapes");
        let dir = tempfile::tempdir().unwrap();
        let path = dir.path().join("q.ps1");
        std::fs::write(
            &path,
            format!(
                "$text = \"x$([char]0x2019);calc;$([char]0x2018)'y\"\n{quoting}\n\
                 $text\n$v = Invoke-Expression $text\nif ($v -ne \"x$([char]0x2019);calc;$([char]0x2018)'y\") {{ exit 1 }}\n"
            ),
        )
        .unwrap();
        match std::process::Command::new("pwsh")
            .args(["-NoProfile", "-NonInteractive", "-File"])
            .arg(&path)
            .output()
        {
            Ok(o) => assert!(
                o.status.success(),
                "{}{}",
                String::from_utf8_lossy(&o.stdout),
                String::from_utf8_lossy(&o.stderr)
            ),
            Err(_) => eprintln!("pwsh not installed; skipped"),
        }
    }

    /// The helper's side reads files and builds no client: neither this
    /// module nor [`crate::names`] (the recorder aside, which only hears
    /// of reads) names client code.
    #[test]
    fn the_helper_path_depends_on_no_client_code() {
        for (file, src) in [
            ("completions.rs", include_str!("completions.rs")),
            ("names/mod.rs", include_str!("../names/mod.rs")),
            ("main.rs", include_str!("../main.rs")),
        ] {
            let code: String = src
                .lines()
                .filter(|l| !l.trim_start().starts_with("//"))
                .take_while(|l| !l.starts_with("#[cfg(test)]"))
                .collect::<Vec<_>>()
                .join("\n");
            for banned in [
                "pce::",
                "PceClient",
                "Context",
                "resolve(",
                "identity(",
                "secret",
                "Command::new",
            ] {
                assert!(!code.contains(banned), "{file} uses {banned}");
            }
        }
        // main hands `__complete` to the helper before clap and the runtime.
        let main = include_str!("../main.rs");
        let helper = main.find("completions::helper(").unwrap();
        assert!(helper < main.find("Cli::parse_from(").unwrap());
        assert!(helper < main.find("tokio::runtime").unwrap());
    }

    /// The scripts parse in the real shells, when they are installed.
    #[test]
    fn scripts_parse_in_their_shells() {
        for (shell, bin) in [
            (Shell::Bash, "bash"),
            (Shell::Zsh, "zsh"),
            (Shell::Fish, "fish"),
            (Shell::PowerShell, "pwsh"),
        ] {
            let dir = tempfile::tempdir().unwrap();
            let path = dir.path().join("script");
            std::fs::write(&path, script(shell)).unwrap();
            let mut cmd = std::process::Command::new(bin);
            match bin {
                "fish" => cmd.arg("--no-execute").arg(&path),
                "pwsh" => cmd.args(["-NoProfile", "-NonInteractive", "-Command"]).arg(format!(
                    "$e = $null; [void][System.Management.Automation.Language.Parser]::ParseFile('{}', [ref]$null, [ref]$e); if ($e) {{ $e | Out-String | Write-Error; exit 1 }}",
                    path.display()
                )),
                _ => cmd.arg("-n").arg(&path),
            };
            match cmd.output() {
                Ok(o) => assert!(
                    o.status.success(),
                    "{bin} -n: {}",
                    String::from_utf8_lossy(&o.stderr)
                ),
                Err(_) => eprintln!("{bin} not installed; skipped"),
            }
        }
    }
}
